      aliases: ["Perforomist", "formoterol fumarate", "rapid onset LABA", "Foradil", "formoteral"],
      brandExamples: ["Perforomist"],
      class: "Rapid-onset, approximately 12-hour long-acting beta2-adrenergic agonist (LABA)",
