      populationRisks: populationRisks("Age and role depend on the exact standalone or combination product; never extrapolate across devices.", "Older adults have greater arrhythmia, ischemia, and electrolyte vulnerability.", "Use when needed for maternal respiratory control with an individualized pregnancy and lactation plan."),
      sourceNote: "Current U.S. PERFOROMIST labeling and GINA 2026 strategy: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=fb2fe258-fe2e-47f6-8adf-ca75bf6f90af ; https://ginasthma.org/wp-content/uploads/2026/05/GINA-2026-Strategy-Report-WMS.pdf",
      tags: ["frontier-wave8", "pulmonary", "formoterol", "Perforomist", "LABA", "rapid onset", "AIR", "MART"]
